"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["13054"],{94376(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.conflito_de_concorrencia","status":409,"titulo":"O rascunho foi modificado concorrentemente"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.conflito_de_concorrencia","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["Duas escritas sobre o mesmo termo aconteceram ao mesmo tempo, e esta chegou depois: outra edi\xe7\xe3o do rascunho, outra marca\xe7\xe3o de revis\xe3o ou outra promo\xe7\xe3o j\xe1 tinha sido confirmada entre a leitura do termo e a grava\xe7\xe3o desta opera\xe7\xe3o. Atinge a edi\xe7\xe3o do rascunho (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`), a marca\xe7\xe3o de revis\xe3o (`POST .../revisar`) e a promo\xe7\xe3o (`POST .../promover`). Nada \xe9 gravado pela opera\xe7\xe3o recusada.","A recusa \xe9 deliberada. Editar o rascunho limpa a marca de revis\xe3o, porque a revis\xe3o vale para o texto exato que foi lido (UNI-REQ-0086). Se a API repetisse sozinha um pedido de revis\xe3o ou de promo\xe7\xe3o, ela poderia aprovar um texto novo que ningu\xe9m revisou. Por isso a resposta n\xe3o indica que repetir a mesma requisi\xe7\xe3o resolve, ao contr\xe1rio do que ocorre com outros conflitos de concorr\xeancia do m\xf3dulo."],"comoResolver":["Consulte o termo (`GET /api/configuracao/termos-consentimento/{id}`) e confira o rascunho e a marca de revis\xe3o atuais. S\xf3 depois de ler o texto que est\xe1 valendo repita a opera\xe7\xe3o: edite de novo o rascunho, marque a revis\xe3o do texto que voc\xea leu ou promova a vers\xe3o."],"ondeAparece":["Edi\xe7\xe3o do rascunho de um termo de consentimento","Marca\xe7\xe3o do rascunho de um termo de consentimento como revisado","Promo\xe7\xe3o do rascunho de um termo de consentimento a vers\xe3o"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);